import { useState } from "react";

export default function AdminMenu() {
  const [menu, setMenu] = useState([
    { id: 1, name: "Idli & Sambar", category: "Breakfast", price: 35, available: true },
    { id: 2, name: "Masala Dosa", category: "Breakfast", price: 45, available: true }
  ]);

  const [form, setForm] = useState({
    name: "", category: "Breakfast", price: "", available: true
  });

  function saveItem() {
    setMenu([...menu, { ...form, id: Date.now() }]);
    setForm({ name: "", category: "Breakfast", price: "", available: true });
  }

  return (
    <div className="admin-grid-two">
      <div>
        <h3 className="section-title">Menu Items</h3>
        <table>
          <thead>
            <tr>
              <th>Item</th><th>Category</th><th>Price</th><th>Available</th>
            </tr>
          </thead>
          <tbody>
            {menu.map(item => (
              <tr key={item.id}>
                <td>{item.name}</td>
                <td>{item.category}</td>
                <td>{item.price}</td>
                <td>{item.available ? "Yes" : "No"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div>
        <h3 className="section-title">Add Item</h3>
        <input placeholder="Item name" value={form.name}
          onChange={e => setForm({ ...form, name: e.target.value })} />
        <input type="number" placeholder="Price" value={form.price}
          onChange={e => setForm({ ...form, price: e.target.value })} />
        <button className="btn btn-primary btn-sm" onClick={saveItem}>
          Save Item
        </button>
      </div>
    </div>
  );
}
